window.BEATS = {"bpm":120,"beat":0.5,"offset":0,"beats":[],"nominal":true};
window.VO = [{"id":"n01","text":"Your physics book says the Tacoma Narrows Bridge fell because of resonance.","at":0.24,"t0":0.12,"t1":4.25},{"id":"n02","text":"Most engineers now say it didn't.","at":9.1,"t0":4.55,"t1":6.37},{"id":"n03","text":"Resonance is a push in rhythm, like pushing a swing.","at":14.14,"t0":7.07,"t1":10.09},{"id":"n04","text":"That morning the wind was steady. It wasn't pushing in time with the bridge.","at":21.18,"t0":10.59,"t1":14.535},{"id":"n05","text":"So what shook it?","at":30.07,"t0":15.035,"t1":16.1},{"id":"n06","text":"The bridge did.","at":34,"t0":17,"t1":17.97},{"id":"n07","text":"Its deck was shallow and solid. It caught the wind like a wing.","at":37.54,"t0":18.77,"t1":22.325},{"id":"n08","text":"Each twist tipped it into the wind, and the wind pushed the twist further.","at":45.35,"t0":22.675,"t1":26.485},{"id":"n09","text":"Every twist fed the next. Engineers call it flutter.","at":53.67,"t0":26.835,"t1":29.915},{"id":"n10","text":"An hour later, the middle of the deck tore away.","at":61.23,"t0":30.615,"t1":33.22},{"id":"n11","text":"Now big bridges are tested in a wind tunnel before they're built.","at":68.24,"t0":34.12,"t1":37.63}];
